from pathlib import Path
p=Path('/mnt/data/patch14/src/utils/vpsManager.js')
s=p.read_text()
start=s.index('async function listAllActiveInstances() {')
end=s.index('\nasync function getVpsInstance', start)
new='''async function listAllActiveInstances() {\n  // Gabungkan data order normal (vps_instances) + data renter hasil backup/restore\n  // (renter_instances). Ini membuat menu Admin > List VPS&RDP tetap menampilkan\n  // server lama yang direstore dari backup renter, bukan hanya order baru.\n  const normalRows = await db.all(\n    `SELECT vi.id, vi.user_id, vi.api_id, vi.product_id, vi.droplet_id, vi.ip, vi.region, vi.image,\n            vi.created_at, vi.expires_at, vi.duration_days,\n            vp.product_type, vp.size_slug, vp.ram, vp.core, a.email as api_email,\n            'order' as source\n     FROM vps_instances vi\n     LEFT JOIN vps_products vp ON vp.id = vi.product_id\n     LEFT JOIN do_api a ON a.id = vi.api_id\n     WHERE vi.status = 1`\n  );\n\n  let renterRows = [];\n  try {\n    renterRows = await db.all(\n      `SELECT ri.id, ri.user_id, ri.api_id, NULL as product_id, ri.droplet_id, ri.ip, ri.region, ri.image,\n              ri.created_at, r.expires_at as expires_at, NULL as duration_days,\n              ri.type as product_type, ri.size_slug, NULL as ram, NULL as core, ra.email as api_email,\n              'renter' as source\n       FROM renter_instances ri\n       LEFT JOIN renters r ON r.user_id = ri.user_id\n       LEFT JOIN renter_do_api ra ON ra.id = ri.api_id\n       WHERE ri.status = 1`\n    );\n  } catch (_) {\n    // Tabel renter belum ada di DB lama. Abaikan agar list order normal tetap jalan.\n    renterRows = [];\n  }\n\n  const rows = [...(normalRows || []), ...(renterRows || [])];\n  rows.sort((a, b) => {\n    const ae = Number(a.expires_at || 9999999999);\n    const be = Number(b.expires_at || 9999999999);\n    if (ae !== be) return ae - be;\n    return Number(b.created_at || b.id || 0) - Number(a.created_at || a.id || 0);\n  });\n  return rows;\n}\n'''
p.write_text(s[:start]+new+s[end:])
print('patched')
